       .err { color: var(--paper); }
       a { display: inline-block; margin-top: 24px; padding: 10px 14px; border: 1px solid var(--green); color: var(--green); font-size: 12px; text-decoration: none; }
       a:hover, a:focus-visible { background: var(--green); color: var(--ink); outline: none; }
       .cursor { display: inline-block; width: 8px; height: 14px; margin-left: 4px; background: var(--green); vertical-align: -2px; animation: blink 1s steps(1) infinite; }
       @keyframes blink { 50% { opacity: 0; } }
       @media (prefers-reduced-motion: reduce) { .cursor { animation: none; } }
     </style>
   </head>
   <body>
     <main>
       <p class="bar">guest@portfolio:~$ cd <span id="path"></span></p>
       <h1>404</h1>
       <p class="err" id="error"></p>
       <p id="hint"></p>
       <p id="game-hint"></p>
       <div class="game-box"><canvas id="dino-canvas" width="900" height="260" aria-label="Dino game"></canvas></div>
       <a href="index.html" id="home"></a><span class="cursor" aria-hidden="true"></span>
     </main>
     <script>
       const read = (key) => { try { return localStorage.getItem(key); } catch { return null; } };
       const savedTheme = read("portfolio-theme");
       const theme = savedTheme === "solar" ? "claude" : savedTheme;
       document.body.dataset.theme = ["hacker", "cyberpunk", "claude"].includes(theme) ? theme : "hacker";
       const es = read("portfolio-language") !== "en";
       document.documentElement.lang = es ? "es" : "en";
       document.getElementById("path").textContent = new URLSearchParams(location.search).get("from") || location.pathname;
       document.getElementById("error").textContent = es ? "bash: cd: no existe el archivo o directorio" : "bash: cd: no such file or directory";
       document.getElementById("hint").textContent = es ? "La página que buscas no existe o se ha movido." : "The page you are looking for does not exist or has moved.";
       document.getElementById("game-hint").textContent = es ? "Mientras tanto: ESPACIO / ↑ saltar, ↓ agacharse. En móvil: toca arriba para saltar y mantén abajo para agacharte." : "Meanwhile: SPACE / ↑ jump, ↓ duck. On mobile: tap the top to jump, hold the bottom to duck.";
       document.getElementById("home").textContent = es ? "[ volver al inicio ]" : "[ back to home ]";
     </script>
     <script type="importmap">
       {
         "imports": {
           "assets/": "./assets/"
         }
       }
     </script>
     <script type="module" src="assets/functions/dinoGame/dinoGame.js"></script>
   </body>
 </html>

