}
@media (prefers-reduced-motion: reduce) {
  .screen.is-active { animation: none; }
  .skill-fill { animation: none; }
}
.wordmark { text-decoration: none; }
.route-bar { display: flex; align-items: center; gap: 9px; margin-left: auto; color: var(--green); font-size: 10px; white-space: nowrap; }
.route-prompt { color: var(--muted); }
.route-bar a { color: var(--green); }
.route-bar a:hover { text-decoration: none; }
#route-page { color: var(--cyan); }
.home-screen.is-active { grid-template-columns: minmax(0, 0.85fr) minmax(320px, 1.15fr); gap: clamp(28px, 5vw, 72px); overflow: hidden; }
.home-content { min-width: 0; }
.home-directory {
  align-self: center;
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 9px;
  perspective: 760px;
  perspective-origin: center bottom;
}
.home-directory .directory-heading {
  width: 100%;
}
.home-directory .menu-item.folder-tile {
  flex: 0 0 calc(33.333% - 6px);
  max-width: calc(33.333% - 6px);
}
.directory-heading { grid-column: 1 / -1; min-height: 34px; display: flex; align-items: center; justify-content: space-between; gap: 12px; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.directory-heading > span:last-child { color: var(--green-dim); font-size: 8px; }
.menu-item.folder-tile { position: relative; min-height: 112px; display: grid; grid-template-columns: minmax(0, 1fr) 18px; grid-template-rows: 1fr auto auto; align-items: end; gap: 5px 8px; padding: 12px; border: 1px solid var(--green); border-radius: 5px; background: var(--ink); color: var(--green); text-decoration: none; perspective: 600px; transform-style: flat; transition: transform .3s cubic-bezier(0.175, 0.885, 0.32, 1.275), border-color .18s ease, background-color .18s ease, color .18s ease; }
.menu-item.folder-tile:not(.is-dragging):active, .menu-item.folder-tile.is-pressed { transform: scale(0.97) !important; transition: transform .3s cubic-bezier(0.175, 0.885, 0.32, 1.275) !important; }
.menu-item.folder-tile .folder-back::before { position: absolute; top: -9px; left: -1px; width: 38%; height: 9px; border: 1px solid var(--green-dim); border-bottom: 0; border-radius: 5px 5px 0 0; background: var(--green-dim); content: ""; }
.menu-item.folder-tile:hover { z-index: 2; border-color: var(--ink); background: transparent; color: var(--ink); }
.menu-item.folder-tile:focus-visible { outline: 0; }
.menu-item.folder-tile > * { position: relative; z-index: 5; }
.menu-item.folder-tile > .menu-index, .menu-item.folder-tile > .folder-name, .menu-item.folder-tile > .folder-meta, .menu-item.folder-tile > .menu-arrow { position: relative; z-index: 5; }
.menu-item.folder-tile .folder-back { position: absolute; z-index: 1; right: 4px; bottom: 4px; left: 4px; height: 88%; border: 1px solid var(--green-dim); border-radius: 0 8px 8px 8px; background: var(--green-dim); }
.menu-item.folder-tile .folder-file { position: absolute; z-index: 2; bottom: 10px; left: 15px; width: calc(100% - 30px); height: 68%; border: 1px solid var(--line); border-radius: 4px; background: var(--paper); box-shadow: 0 2px 5px rgba(0, 0, 0, .14); opacity: 1; transition: transform .3s ease-out; }
.menu-item.folder-tile .folder-file-1 { transform: translateY(0); }
.menu-item.folder-tile .folder-file-2 { transform: translate(5px, -5px) rotate(2deg); }
.menu-item.folder-tile .folder-front { position: absolute; z-index: 4; right: 4px; bottom: 4px; left: 4px; height: 88%; border: 2px solid var(--ink); border-radius: 0 8px 8px 8px; background: var(--green); box-shadow: 0 4px 10px rgba(0, 0, 0, .22); transform: rotateX(0); transform-origin: bottom center; backface-visibility: visible; transition: transform .3s ease-out, background-color .3s ease-out; }
.menu-item.folder-tile:hover .folder-front { transform: rotateX(-40deg); background: color-mix(in srgb, var(--green) 78%, var(--ink)); }
.menu-item.folder-tile:hover .folder-file-1 { transform: translateY(-20px); }
.menu-item.folder-tile:hover .folder-file-2 { transform: translateY(-25px) translate(5px, -5px) rotate(4deg); }
.menu-index { grid-column: 2; grid-row: 1; justify-self: end; color: var(--green); font-size: 8px; }
.folder-name { grid-column: 1; grid-row: 2; color: inherit; font-size: 12px; }
.folder-meta { grid-column: 1; grid-row: 3; color: var(--green-dim); font-size: 7px; }
.menu-item.folder-tile .menu-arrow { grid-column: 3; grid-row: 2 / 4; align-self: center; justify-self: end; }
.menu-item.folder-tile .menu-arrow { grid-column: 2; }
.menu-item.folder-tile > .menu-index, .menu-item.folder-tile > .folder-name, .menu-item.folder-tile > .folder-meta, .menu-item.folder-tile > .menu-arrow { color: var(--ink); opacity: 1; transition: opacity .3s ease-out; }
.menu-item.folder-tile:hover > .menu-index, .menu-item.folder-tile:hover > .folder-name, .menu-item.folder-tile:hover > .folder-meta, .menu-item.folder-tile:hover > .menu-arrow { opacity: 0; }
.menu-item.folder-tile.is-selected::before, .menu-item.folder-tile.is-option-selected::before { border-color: var(--ink); background: var(--green); }
.menu-item.folder-tile.is-selected .menu-index, .menu-item.folder-tile.is-option-selected .menu-index,
.menu-item.folder-tile.is-selected .folder-meta, .menu-item.folder-tile.is-option-selected .folder-meta,
.menu-item.folder-tile.is-selected .menu-arrow, .menu-item.folder-tile.is-option-selected .menu-arrow { color: var(--ink); }
.directory-hint { grid-column: 1 / -1; margin: 6px 0 0; color: var(--muted); font-size: 8px; }
.directory-hint kbd { display: inline-block; margin-right: 3px; padding: 3px 5px; border: 1px solid var(--line); color: var(--paper); font: 8px var(--mono); }
.directory-hint kbd:nth-of-type(2) { margin-right: 8px; }
.home-screen .hero-topline { margin-bottom: 31px; }
.home-screen h1 { font-size: clamp(53px, 7vw, 88px); }
.home-screen .intro { font-size: 12px; }
.page-controls { gap: 18px; }
.page-progress { gap: 8px; }
.option-label { color: var(--green-dim); font-size: 8px; }
.keyboard-hint { font-size: 8px; }
.is-option-selected:not(.menu-item) { outline: 1px solid var(--green-dim); outline-offset: 3px; }
.skill-group.is-option-selected { outline-offset: 5px; }
.experience-card.is-option-selected, .project-card.is-option-selected { border-color: var(--green); }
.contact-chip.is-option-selected, .cv-link.is-option-selected { outline-offset: 3px; }
.route-bar, .route-bar a, #route-page { color: var(--green); }
.route-bar { gap: 4px; }
.page-controls { justify-content: space-between; }
.keyboard-hint { margin-left: 0; }
.control-pickers { display: flex; align-items: center; gap: 8px; }
@media (max-width: 760px) {
  .topbar { min-height: 91px; }
  .route-bar { order: 3; width: 100%; margin: 7px 0 0; font-size: 9px; }
  .home-screen.is-active { grid-template-columns: minmax(0, 1fr); align-content: start; gap: 25px; overflow: hidden; }
  .home-screen .hero-topline { margin-bottom: 20px; }
