}
@media (min-width: 761px) and (max-height: 760px) {
  #screen-about { padding-block: 24px; }
}
@media (min-width: 1300px) {
  .page-shell { width: 100%; max-width: 100%; padding: 0 48px; }
  .home-content { max-width: 1100px; }
  .intro { max-width: 880px; }
  .hero-rule, .home-menu { width: min(100%, 880px); }
  .project-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
}

/* Interactive Elements Press + Spring Effect */
button,
a,
.menu-item,
.index-tile,
.folder-tile:not(.is-dragging),
.cv-link,
.contact-chip,
.send-button,
.project-row,
.topic-folder:not(.is-dragging),
.pager-button,
#page-dots button,
.theme-option,
.lang-option,
.terminal-btn {
  transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), background-color 0.18s ease, color 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

button:active,
a:active,
.menu-item:active,
.index-tile:active,
.folder-tile:not(.is-dragging):active,
.cv-link:active,
.contact-chip:active,
.send-button:active,
.project-row:active,
.topic-folder:not(.is-dragging):active,
.pager-button:active,
#page-dots button:active,
.theme-option:active,
.lang-option:active,
.terminal-btn:active {
  transform: scale(0.97);
}
  .skills-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
}
@media (min-width: 1700px) {
  .page-shell { width: 100%; max-width: 100%; padding: 0 64px; }
  .home-content { max-width: 1300px; }
  .intro { max-width: 1020px; }
  .hero-rule, .home-menu { width: min(100%, 1020px); }
  .project-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; }
}

@media (max-width: 768px) {
  .page-shell {
    width: 100%;
    height: 100vh;
    height: 100svh;
    border: none;
    padding: 0 16px;
  }
  .screen {
    padding: 20px 16px;
  }
  .home-screen.is-active {
    grid-template-columns: 1fr;
  }
  .about-contact-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
}

before.content:
:root {
