    padding: 20px 16px;
  }
  .home-screen.is-active {
    grid-template-columns: 1fr;
  }
  .about-contact-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
}

before.content:
:root {
  color-scheme: dark;
  --ink: #090b0a;
  --panel: #0d100e;
  --panel-raised: #111512;
  --line: #2b322d;
  --muted: #9aa39a;
  --paper: #e9eee8;
  --green: #20ef4f;
  --green-dim: #087d2a;
  --cyan: #91f3a8;
  --grid-line: rgba(32, 239, 79, .025);
  --orb-core: #010602;
  --orb-glow: #20ef4f;
  --mono: "DM Mono", "Courier New", monospace;
  --display: "Space Grotesk", "Trebuchet MS", sans-serif;
  font-family: var(--mono);
  background: var(--ink);
  color: var(--paper);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}
* { box-sizing: border-box; }
html, body {
  width: 100vw;
  height: 100vh;
  overflow: hidden;
