  visibility: hidden;
  pointer-events: none;
}
.bios-content {
  max-width: 800px;
}
.bios-line {
  margin: 0 0 4px 0;
  white-space: pre-wrap;
  opacity: 0;
  animation: biosFadeIn 0.1s forwards;
}
