/* BIOS Boot Screen */
.bios-boot-screen {
  position: fixed;
  inset: 0;
  background: #000;
  color: #c0c0c0;
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1.6;
  z-index: 99999;
  padding: 48px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  cursor: pointer;
  transition: opacity 0.5s ease, visibility 0.5s ease;
}
.bios-boot-screen.is-hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}
.bios-content {
  max-width: 800px;
}
.bios-line {
  margin: 0 0 4px 0;
  white-space: pre-wrap;
  opacity: 0;
  animation: biosFadeIn 0.1s forwards;
}
.bios-persistent {
  margin: 0 0 4px 0;
  white-space: pre-wrap;
  opacity: 1;
}
.bios-line:nth-child(1) { animation-delay: 0.1s; }
.bios-line:nth-child(2) { animation-delay: 0.25s; }
.bios-line:nth-child(3) { animation-delay: 0.4s; }
.bios-line:nth-child(4) { animation-delay: 0.55s; }
.bios-line:nth-child(5) { animation-delay: 0.7s; }
.bios-line:nth-child(6) { animation-delay: 0.85s; }
.bios-line:nth-child(7) { animation-delay: 1.05s; }
.bios-line:nth-child(8) { animation-delay: 1.25s; }
.bios-line:nth-child(9) { animation-delay: 1.45s; }
.bios-line:nth-child(10) { animation-delay: 1.65s; }
.bios-line:nth-child(11) { animation-delay: 1.85s; }
.bios-line:nth-child(12) { animation-delay: 2.1s; }
.bios-line:nth-child(13) { animation-delay: 2.35s; }
.bios-line:nth-child(14) { animation-delay: 2.6s; }
.bios-line:nth-child(15) { animation-delay: 2.85s; }
.bios-line:nth-child(16) { animation-delay: 3.1s; }
.bios-line:nth-child(17) { animation-delay: 3.35s; }
.bios-line:nth-child(18) { animation-delay: 3.6s; }
.bios-line:nth-child(19) { animation-delay: 3.9s; }
.bios-line:nth-child(20) { animation-delay: 4.2s; }
.bios-line:nth-child(21) { animation-delay: 4.5s; }
.bios-line:nth-child(22) { animation-delay: 4.8s; }
.bios-line:nth-child(23) { animation-delay: 5.2s; }
.bios-line:nth-child(24) { animation-delay: 5.6s; }
.bios-line:nth-child(25) { animation-delay: 6.0s; }
.bios-line:nth-child(26) { animation-delay: 6.4s; }

.bios-green {
  color: var(--green);
}
.bios-dim {
  color: var(--muted);
}
.bios-footer {
  display: flex;
  justify-content: space-between;
  color: #fff;
  background: #0000aa;
  padding: 6px 12px;
  font-size: 13px;
  font-weight: bold;
}
@keyframes biosFadeIn {
  to { opacity: 1; }
}
@media (max-height: 640px) {
  .menu-item.folder-tile .folder-icon { width: 19px; height: 13px; }
  .menu-item.folder-tile .folder-icon::before { top: -4px; width: 7px; height: 3px; }
  .folder-name { font-size: 9px; }
  .folder-meta { font-size: 6px; }
