  --muted: #9aa39a;
  --paper: #e9eee8;
  --green: #20ef4f;
  --green-dim: #087d2a;
  --cyan: #91f3a8;
  --grid-line: rgba(32, 239, 79, .025);
  --orb-core: #010602;
  --orb-glow: #20ef4f;
