/* Interactive Elements Press + Spring Effect */
button,
a,
.menu-item,
.index-tile,
.folder-tile:not(.is-dragging),
.cv-link,
.contact-chip,
.send-button,
.project-row,
.topic-folder:not(.is-dragging),
.pager-button,
#page-dots button,
.theme-option,
