   z-index: 99;
   display: none;
 }
 body[data-theme="custom"] .custom-theme-panel {
   display: block;
 }
 .custom-theme-header {
   display: flex;
   justify-content: space-between;
   align-items: center;
   margin-bottom: 10px;
   font-weight: 500;
   letter-spacing: 0.05em;
   color: var(--green);
 }
 .custom-theme-header button {
   background: none;
   border: none;
   color: var(--muted);
   cursor: pointer;
   font-size: 14px;
 }
 .custom-theme-inputs {
   display: flex;
   flex-direction: column;
   gap: 8px;
 }
 .custom-theme-inputs label {
   display: flex;
   justify-content: space-between;
   align-items: center;
   gap: 8px;
 }
 .custom-theme-inputs input[type="color"] {
   appearance: none;
   -webkit-appearance: none;
   border: 1px solid var(--line);
   width: 28px;
   height: 20px;
   background: var(--panel);
   cursor: pointer;
   padding: 0;
 }
 .custom-theme-footer {
   margin-top: 10px;
   text-align: right;
 }
 .custom-theme-footer button {
   background: var(--panel);
   border: 1px solid var(--line);
   color: var(--paper);
   padding: 4px 8px;
   font-family: var(--font-mono);
   font-size: 10px;
   cursor: pointer;
 }
 .custom-theme-footer button:hover {
   border-color: var(--green);
   color: var(--green);
 }

