  // Activate custom theme and set custom colors to something non-green (e.g. blue/purple)
  document.body.dataset.theme = "custom";
  document.body.style.setProperty('--custom-green', '#ff0055');
  document.body.style.setProperty('--custom-cyan', '#00f0ff');
  document.body.style.setProperty('--custom-line', '#330033');
  document.body.style.setProperty('--green', '#ff0055');
  document.body.style.setProperty('--cyan', '#00f0ff');
  document.body.style.setProperty('--line', '#330033');

  // Find all elements and check if any computed color is green (#20ef4f or rgb(32, 239, 79))
  const all = document.querySelectorAll('*');
  const greenElements = [];
  for (const el of all) {
    const comp = getComputedStyle(el);
    const color = comp.color;
    const bg = comp.backgroundColor;
    const border = comp.borderColor;
    if (color.includes('32, 239') || bg.includes('32, 239') || border.includes('32, 239') ||
        color.includes('rgb(32, 239') || bg.includes('rgb(32, 239')) {
      greenElements.push({
        tag: el.tagName,
        class: el.className,
        id: el.id,
        color, bg, border
      });
    }
  }
  return greenElements.slice(0, 20);
});

