  --line: #4a1018;
  --muted: #a88487;
  --paper: #f3e7e8;
  --green: #ed1b2e;
  --green-dim: #8b1020;
  --cyan: #ff727b;
  --grid-line: rgba(237, 27, 46, .035);
  --orb-core: #080406;
  --orb-glow: #ed1b2e;
}
body[data-theme="claude"] {
  color-scheme: light;
  --ink: #f7f0df;
  --panel: #fffaf0;
  --panel-raised: #fffdf7;
  --line: #d8c9ae;
  --muted: #756c61;
  --paper: #253248;
  --green: #d35445;
  --green-dim: #a53b33;
  --cyan: #375f7a;
  --grid-line: rgba(55, 95, 122, .08);
  --orb-core: #fff4df;
  --orb-glow: #d35445;
}
body[data-theme="claude"] .terminal-frame,
