return await page.evaluate(() => {
  const all = document.querySelectorAll('*');
  const results = [];
  for (const el of all) {
    const comp = getComputedStyle(el);
    const color = comp.color;
    const bg = comp.backgroundColor;
    const border = comp.borderColor;
    const fill = comp.fill;
    const stroke = comp.stroke;

    // Check for green (rgb(32, 239, 79) or #20ef4f or rgb(8, 125, 42) or similar green values)
    const isGreen = (str) => {
      if (!str) return false;
      if (str.includes('#20ef4f') || str.includes('#087d2a')) return true;
      const m = str.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
      if (m) {
        const r = parseInt(m[1]), g = parseInt(m[2]), b = parseInt(m[3]);
        // Green dominant and g > r + 30 and g > b + 30
        return g > 150 && g > r + 30 && g > b + 30;
      }
      return false;
    };

