body[data-theme="cyberpunk"] {
  --ink: #080406;
  --panel: #12080a;
  --panel-raised: #1b0b0f;
  --line: #4a1018;
  --muted: #a88487;
  --paper: #f3e7e8;
  --green: #ed1b2e;
  --green-dim: #8b1020;
  --cyan: #ff727b;
  --grid-line: rgba(237, 27, 46, .035);
  --orb-core: #080406;
  --orb-glow: #ed1b2e;
}
body[data-theme="claude"] {
  color-scheme: light;
  --ink: #f7f0df;
  --panel: #fffaf0;
  --panel-raised: #fffdf7;
  --line: #d8c9ae;
  --muted: #756c61;
  --paper: #253248;
  --green: #d35445;
  --green-dim: #a53b33;
  --cyan: #375f7a;
  --grid-line: rgba(55, 95, 122, .08);
  --orb-core: #fff4df;
  --orb-glow: #d35445;
}
body[data-theme="claude"] .terminal-frame,
body[data-theme="claude"] #stage { background: rgba(255, 250, 240, .94); }
body[data-theme="claude"] .site-nav a,
body[data-theme="claude"] .site-nav button,
body[data-theme="claude"] .intro,
body[data-theme="claude"] .tile-detail,
body[data-theme="claude"] .skill-group p,
body[data-theme="claude"] .about-copy,
body[data-theme="claude"] .contact-copy,
body[data-theme="claude"] .skill-name,
body[data-theme="claude"] .experience-card p,
body[data-theme="claude"] .project-card p,
body[data-theme="claude"] .contact-chip,
body[data-theme="claude"] .folder-entry p { color: var(--muted); }
body[data-theme="claude"] .command-dock { border-color: var(--line); background: var(--panel-raised); color: var(--paper); }
body[data-theme="claude"] .skill-bar,
body[data-theme="claude"] .folder-panel { background-color: var(--panel-raised); }
body[data-theme="claude"] .folder-panel::before {
  background: repeating-linear-gradient(to bottom, transparent 0 3px, rgba(37, 50, 72, .035) 3px 4px), radial-gradient(ellipse at center, transparent 55%, rgba(37, 50, 72, .08) 100%);
}
body[data-theme="claude"] .menu-item.is-selected,
body[data-theme="claude"] .cv-link.is-option-selected,
body[data-theme="claude"] .send-button.is-option-selected { background: color-mix(in srgb, var(--green) 10%, transparent); }
body[data-theme="custom"] {
  --ink: #040608;
  --panel: #0a1016;
  --panel-raised: #121c26;
  --line: var(--custom-line, #223548);
  --muted: #829cb5;
  --paper: #e2f0ff;
  --green: var(--custom-green, #20ef4f);
  --green-dim: color-mix(in srgb, var(--green) 50%, #000);
  --cyan: var(--custom-cyan, #37f495);
  --grid-line: color-mix(in srgb, var(--green) 10%, transparent);
  --orb-core: #040608;
  --orb-glow: var(--green);
}
.theme-picker { position: relative; z-index: 8; isolation: isolate; flex: 0 0 56px; width: 56px; height: 56px; margin-left: 0; background: color-mix(in srgb, var(--panel) 92%, transparent); backdrop-filter: blur(12px); border: 1px solid var(--line); border-radius: 8px; box-shadow: 0 4px 20px rgba(0, 0, 0, .3); transition: flex-basis .3s cubic-bezier(0.16, 1, 0.3, 1), width .3s cubic-bezier(0.16, 1, 0.3, 1), border-color .2s ease, box-shadow .3s ease; }
.theme-picker:hover, .theme-picker:focus-within { flex-basis: 224px; width: 224px; border-color: var(--green); box-shadow: 0 8px 32px color-mix(in srgb, var(--green) 25%, rgba(0, 0, 0, .5)); }
.theme-picker.is-collapsed, .theme-picker.is-collapsed:hover, .theme-picker.is-collapsed:focus-within { flex-basis: 56px; width: 56px; border-color: var(--line); box-shadow: 0 4px 20px rgba(0, 0, 0, .3); }
.theme-picker::before { position: absolute; z-index: 0; inset: 2px; border: 1px solid var(--green); border-radius: 6px; background: var(--ink); content: ""; opacity: 0; pointer-events: none; transition: opacity .2s ease; }
.theme-picker:hover::before, .theme-picker:focus-within::before { opacity: 1; }
.theme-picker.is-collapsed::before, .theme-picker.is-collapsed:hover::before, .theme-picker.is-collapsed:focus-within::before { opacity: 0; }
.theme-toggle { position: absolute; z-index: 1; inset: 0 auto 0 0; width: 56px; height: 56px; display: grid; place-items: center; }
.theme-orb { position: relative; width: 30px; height: 30px; border-radius: 50%; background: radial-gradient(circle, var(--orb-core) 0 39%, color-mix(in srgb, var(--orb-glow) 75%, var(--orb-core)) 74%, var(--orb-glow) 100%); box-shadow: 0 0 13px 3px var(--orb-glow), inset 0 0 12px var(--orb-glow); transition: box-shadow .2s ease; }
.theme-orb::before { position: absolute; inset: -7px; border: 1px solid var(--orb-accent, var(--green)); border-radius: 50%; content: ""; }
.theme-picker:hover .theme-toggle .theme-orb, .theme-picker:focus-within .theme-toggle .theme-orb { box-shadow: 0 0 18px 6px var(--orb-glow), inset 0 0 12px var(--orb-glow); }
.theme-choice { position: absolute; z-index: 1; top: 0; width: 56px; height: 56px; display: grid; place-items: center; padding: 0; border: 0; background: transparent; cursor: pointer; opacity: 0; pointer-events: none; transition: opacity .2s ease; }
.theme-next { left: 56px; }
.theme-third { left: 112px; }
.theme-fourth { left: 168px; }
.theme-picker:hover .theme-choice, .theme-picker:focus-within .theme-choice { opacity: 1; pointer-events: auto; }
.theme-picker.is-collapsed .theme-choice, .theme-picker.is-collapsed:hover .theme-choice, .theme-picker.is-collapsed:focus-within .theme-choice { opacity: 0; pointer-events: none; }
.theme-choice:hover .theme-orb, .theme-choice:focus-visible .theme-orb { box-shadow: 0 0 18px 6px var(--orb-glow), inset 0 0 12px var(--orb-glow); }
.theme-orb-next, .theme-orb-third, .theme-orb-fourth { --orb-core: #080406; --orb-glow: #ed1b2e; --orb-accent: #ed1b2e; width: 30px; height: 30px; background: radial-gradient(circle, var(--orb-core) 0 39%, color-mix(in srgb, var(--orb-glow) 75%, var(--orb-core)) 74%, var(--orb-glow) 100%); box-shadow: 0 0 13px 3px var(--orb-glow), inset 0 0 12px var(--orb-glow); }
.theme-orb-next::before, .theme-orb-third::before, .theme-orb-fourth::before { border-color: var(--orb-accent); }
.theme-picker[data-selected-theme="hacker"] .theme-toggle .theme-orb { --orb-core: #010602; --orb-glow: #20ef4f; --orb-accent: #20ef4f; }
.theme-picker[data-selected-theme="cyberpunk"] .theme-toggle .theme-orb { --orb-core: #080406; --orb-glow: #ed1b2e; --orb-accent: #ed1b2e; }
.theme-picker[data-selected-theme="claude"] .theme-toggle .theme-orb { --orb-core: #fff4df; --orb-glow: #d35445; --orb-accent: #d35445; }
.theme-picker[data-selected-theme="custom"] .theme-toggle .theme-orb { --orb-core: #040608; --orb-glow: var(--green); --orb-accent: var(--green); }
.theme-choice[data-theme-choice="hacker"] .theme-orb { --orb-core: #010602; --orb-glow: #20ef4f; --orb-accent: #20ef4f; }
.theme-choice[data-theme-choice="cyberpunk"] .theme-orb { --orb-core: #080406; --orb-glow: #ed1b2e; --orb-accent: #ed1b2e; }
.theme-choice[data-theme-choice="claude"] .theme-orb { --orb-core: #fff4df; --orb-glow: #d35445; --orb-accent: #d35445; }
.theme-choice[data-theme-choice="custom"] .theme-orb { --orb-core: #040608; --orb-glow: var(--green); --orb-accent: var(--green); }

.custom-theme-panel {
  position: absolute;
  bottom: calc(100% + 12px);
  right: 0;
  width: 240px;
  background: var(--panel-raised);
  border: 1px solid var(--line);
  padding: 12px;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--paper);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  z-index: 99;
  display: none;
}
body[data-theme="custom"] .custom-theme-panel {
  display: block;
}
.custom-theme-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
  font-weight: 500;
  letter-spacing: 0.05em;
  color: var(--green);
}
.custom-theme-header button {
  background: none;
  border: none;
  color: var(--muted);
  cursor: pointer;
  font-size: 14px;
}
.custom-theme-inputs {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.custom-theme-inputs label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
}
.custom-theme-inputs input[type="color"] {
  appearance: none;
  -webkit-appearance: none;
  border: 1px solid var(--line);
  width: 28px;
  height: 20px;
  background: var(--panel);
  cursor: pointer;
  padding: 0;
}
.custom-theme-footer {
  margin-top: 10px;
  text-align: right;
}
.custom-theme-footer button {
  background: var(--panel);
  border: 1px solid var(--line);
  color: var(--paper);
  padding: 4px 8px;
  font-family: var(--font-mono);
  font-size: 10px;
  cursor: pointer;
}
.custom-theme-footer button:hover {
  border-color: var(--green);
  color: var(--green);
}

